+/// kernel wakes it on any idle core.
+pub(super) fn frontend_cpu_set(cfg: &RuntimeConfig) -> Option<CpuSet> {
+    let cores = cfg.rust_server_args.cores.as_deref().unwrap_or_default();
+    let mut set = CpuSet::new();
+    for &core in cores {
